import sys

sys.path.insert(0, str(__import__("pathlib").Path(__file__).resolve().parents[4] / "Scripts" / "extraction" / "kit"))
from h import R, NR, D, avail, model, result, conflict, Counter, Tags, row  # noqa: E402

PID = "P092"
# SK-TreePCN completes incomplete TLS tree point clouds (an AdaPoinTr-based transformer trained on simulated LESS point clouds); the individual-tree output evaluated against field measurements is the
# DBH, height and average crown width obtained by QSM reconstruction (AdTree) of the incomplete against the completed clouds of the two field plots (mean of the two plots). The completion scores
# (Chamfer distance and F1 of the completed cloud, Tables 6 and 7) measure the completion, not a tree task, and are not recorded.
def tag(attr):
    return Tags(task="attribute_estimation", level="tree", split="test", agg="mean", attribute=attr)
OBJ_EV = "recovers complete individual tree point clouds from incomplete scanning data in the field"
TRAIN_EV = "SK-TreePCN employs a transformer trained on simulated point clouds generated by a 3D radiative transfer model"
FIELD_EV = "Two field plots (S1 and S2 in Figure 2) were surveyed in November 2022"

ROWS = [
    R("task", "attribute_estimation", 1, "Abstract", "tree height and diameter at breast height extracted from the recovered point cloud", note="point cloud completion of individual trees; the evaluated tree output is DBH, height and crown width from the completed clouds"),
    R("output_unit", "tree_points;tree_attribute", 1, "Abstract", OBJ_EV),
    R("tree_setting", "plantation", 5, "Sec. 2.1", "eucalyptus plantation of Jiangxi Town, Jiangnan District"),
    R("tree_taxa", "Eucalyptus (field plots); nine Eucalyptus species in the simulated data", 5, "Sec. 2.1", "eucalyptus plantation of Jiangxi Town, Jiangnan District"),
    R("study_area", "Jiangxi Town, Jiangnan District, Nanning City, Guangxi, China", 5, "Sec. 2.1", "Nanning City, Guangxi Province"),
    D("biome", "subtropical", "Nanning, Guangxi, China; coded from the study area"),
    R("platform", "terrestrial_lidar", 5, "Sec. 2.1", "Trimble TX8 (Trimble Inc., Sunnyvale, CA, USA)", note="field TLS; the training data are virtual TLS point clouds simulated with LESS"),
    R("sensors", "lidar", 5, "Sec. 2.1", "Trimble TX8 (Trimble Inc., Sunnyvale, CA, USA)"),
    R("annotation_type", "regression_target", 5, "Sec. 2.1", FIELD_EV, note="field-measured DBH, tree height and crown width of the trees of plots S1 and S2"),
    R("dataset_name", "own virtual TLS (LESS simulation) point clouds of nine Eucalyptus species", 1, "Abstract", TRAIN_EV, item="dataset1"),
    R("dataset_key", "own_p092_less_vls", 1, "Abstract", TRAIN_EV, item="dataset1"),
    R("dataset_role", "train_test", 1, "Abstract", TRAIN_EV, item="dataset1", note="simulated data train the completion model and give its ground truth"),
    D("dataset_public", "no", "No data link; data available on request (Data Availability Statement)", item="dataset1"),
    R("dataset_name", "own TLS plots S1 and S2, eucalyptus plantation, Nanning (182 trees)", 5, "Sec. 2.1", FIELD_EV, item="dataset2"),
    R("dataset_key", "own_p092_guangxi_tls", 5, "Sec. 2.1", FIELD_EV, item="dataset2"),
    R("dataset_role", "transfer_target", 5, "Sec. 2.1", FIELD_EV, item="dataset2", note="real data never used for training; simulated to real"),
    R("dataset_public", "on_request", 29, "Data Availability Statement", "The data presented in this study are available on request from the corresponding author", item="dataset2"),
    D("n_trees", "182", "sum of the printed counts of 100 trees in plot S1 and 82 trees in plot S2 (Sec. 2.1)", item="dataset2", unit="trees"),
]
ROWS += model("model1", "SK-TreePCN (AdaPoinTr-based transformer with skeleton modules) with AdTree reconstruction", "proposed", "pure_vit", "AdaPoinTr set-to-set transformer with a skeleton proxy point sampler (SK-PS) and a topology regulator (SK-TA)", "none", "from_scratch", 9, "Sec. 2.3",
              "transforming the point cloud completion task into a set-to-set transformation problem", cat_note="transformer encoder-decoder for point cloud completion (AdaPoinTr baseline); AdTree then reconstructs the tree model",
              pre_page=1, pre_loc="Abstract", pre_ev=TRAIN_EV, pre_note="trained on simulated point clouds only, no pre-training stated", strat_page=1, strat_loc="Abstract", strat_ev=TRAIN_EV,
              strat_note="trained on simulated LESS point clouds and applied to the real field plots")
ROWS += model("model2", "AdTree reconstruction of the incomplete point clouds (no completion)", "other_baseline", "classical", "AdTree QSM reconstruction on the incomplete TLS point cloud", None, None, 22, "Sec. 3.4",
              "Figure 17a,c,e, the first column displayed the fitting results of estimated versus", cat_note="geometric QSM reconstruction, no neural network", pre_status="not_reported", pre_note="not applicable", strat_note="not applicable")
res = Counter("res")
EVB_R2, EVB_RMSE = "0.836, 0.920, and 0.914", "0.847, 0.579, and"
EVA_RMSE = "0.588, 0.528, and 0.181"
ATTR = [  # attribute, label, unit, before R2, before RMSE, after R2, after RMSE, evidence before R2, before RMSE, after R2, after RMSE (page, text)
    ("dbh", "DBH", "cm", "0.836", "0.847", "0.904", "0.588", (22, EVB_R2), (22, EVB_RMSE), (22, "increased to 0.904"), (22, EVA_RMSE)),
    ("height", "tree height", "m", "0.920", "0.579", "0.929", "0.528", (22, EVB_R2), (22, EVB_RMSE), (1, "R2 values of 0.929 and 0.904, respectively"), (22, EVA_RMSE)),
    ("crown_diameter", "average crown width", "m", "0.914", "0.184", "0.916", "0.181", (22, EVB_R2), (22, "0.184"), (22, "0.929, and 0.916"), (22, EVA_RMSE)),
]
for attr, lab, unit, b_r2, b_rm, a_r2, a_rm, e_b_r2, e_b_rm, e_a_r2, e_a_rm in ATTR:
    tg = tag(attr)
    for item, r2, rm, er2, erm, st in (("model2", b_r2, b_rm, e_b_r2, e_b_rm, "AdTree on the incomplete point clouds"), ("model1", a_r2, a_rm, e_a_r2, e_a_rm, "AdTree on the point clouds completed by SK-TreePCN")):
        setting = f"Sec. 3.4: {lab} against field measurement, {st}, mean of plots S1 and S2"
        ROWS += result(res(), "r2", item, "dataset2", r2, er2[0], "Sec. 3.4", er2[1], unit="fraction", setting=setting, note=f"arithmetic mean of the R2 of the two field plots; {lab}", **tg, primary=True)
        ROWS += result(res(), "rmse", item, "dataset2", rm, erm[0], "Sec. 3.4", erm[1], unit=unit, setting=setting, note=f"arithmetic mean of the RMSE of the two field plots; {lab}; unit from the stated change (cm for DBH, m otherwise)", **tg, primary=True)
ROWS += [R("limitations", "Only leafless trees are completed, and differences between simulated and real TLS point clouds limit the transfer of the completion model", 28, "Sec. 4.5", "we focused on leafless trees for two primary reasons"),
         D("code_available", "no", "No code repository or availability statement in the paper"), D("weights_available", "not_stated", "No statement about trained weights"),
         R("data_available", "on_request", 29, "Data Availability Statement", "The data presented in this study are available on request from the corresponding author")]
ROWS += [D("notes", "SK-TreePCN completes incomplete tree point clouds. Its completion scores (Chamfer distance CD1 and CD2 and the F-score at a 1 percent threshold; Tables 6 to 8, simulated and field trees, against PCN, GRNet, TopNet, FoldingNet and AdaPoinTr) measure the completion and are not recorded. The recorded results are the DBH, tree height and average crown width of AdTree models of the incomplete and of the completed field point clouds against field measurements (arithmetic mean R2 and RMSE of plots S1 and S2, Sec. 3.4, Fig. 17). The abstract's R2 of 0.929 (height) and 0.904 (DBH) are the after-completion values. The RMSE units are not printed with the values: the stated changes are in cm for DBH and m for height. The page text of this PDF is partly duplicated.",
           "Sec. 3.4 and Fig. 17 (p. 22)")]
